12	// THE PACK UPDATE FLOW (docs/versioned-updates/DESIGN.md §3): move one repo's
13	// declared packs from the versions it has installed to the ones this canon ships.
14	// The same shape as the engine flow beside it — vendor, migrate, converge, stamp,
15	// gate — with three deliberate differences, each a consequence of what a pack IS:
16	//
17	//   1. IT OWNS `.github/workflows/`, and DELIVERS IT BY WITHHOLDING. The scheduler
18	//      workflow's content is a function of the TASK SET (`declaredSecrets` unions
19	//      the required secrets of every discovered task), so pack changes are what
20	//      rewrite it — and this flow is the only one that runs late enough to see the
21	//      task set it just vendored.
22	//
23	//      What it does NOT have is a credential. Its caller pushes with the Action's
24	//      GITHUB_TOKEN, which GitHub never lets write under `.github/workflows/`, and
25	//      the refusal rejects the WHOLE ref — so a flow that wrote one would not
26	//      deliver a workflow, it would fail the entire update and everything riding on
27	//      it. So this flow computes the content and withholds it: nothing lands on
28	//      disk, the paths ride out in `withheld`, and the apply stage — which has an
29	//      MCP credential — writes them verbatim. That is a CREDENTIAL LANE, not
30	//      adaptation: the content is already decided, and the session supplies only
31	//      the one thing an Action token cannot (#797, #649).
32	//   2. IT ENFORCES `minEngineVersion`. A pack version declares the lowest engine it
33	//      runs on; applying it past that is a guess, and a guess about whether a
34	//      member's engine can load a pack is how a fleet goes quiet. Violation is a
35	//      terminal, never a downgrade to "try anyway".
36	//   3. IT HAS AN AGENTIC TAIL — the one place agentic work survives, because the
37	//      pack's new rules meet member-authored content the canon has never seen. This
38	//      module is the DETERMINISTIC half and ends by saying whether that stage is
39	//      needed; the stage itself belongs to the shell that can dispatch a session.
40	//
41	// Everything else is shared with the engine flow on purpose: the same version
42	// predicate decides the gap, the same self-test gates the merge, and every
43	// non-green end is the same `needs-human` terminal (DESIGN §5).
44	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // <canon>/updates/
45	
46	// A pack's own half of the vendor set: its directory, and nothing else. The engine
47	// tree and the catalog belong to the engine flow, which is what keeps two flows
48	// converging one mount from ever fighting over a file.
49	export const isPackFile = (rel, id) => rel.startsWith(`packs/${id}/`);
50	
51	// The records this repo still needs for one pack, oldest first — the same predicate
52	// the engine flow ranges over, with that pack's number instead of the engine's.
53	export function packRecordsInGap(id, installed, { today } = {}) {
54	  return migrationDirs().filter((d) => {
55	    const of = flowOf(d);
56	    return of.flow === 'pack' && of.pack === id && migrationApplies(d, { installed, today });
57	  });
58	}
59	
60	// What a pack update would do to each declared pack, judged before anything is
61	// written: its installed version, the version this canon ships, whether the repo's
62	// engine satisfies the pack's minimum, and the records in between.
63	//
64	// `blocked` is the whole point of returning this rather than a boolean. A pack the
65	// engine is too old for is not skipped quietly and not applied hopefully — it is
66	// named, with both numbers, because the fix (update the engine first) is a sentence
67	// long and unguessable from a silent no-op.
68	export function planPackUpdates(packs, declared, installed, { today, engineVersion = ENGINE_VERSION } = {}) {
69	  const byId = new Map(packs.map((p) => [p.id, p]));
70	  const plan = [];
71	  for (const entry of resolveDeclaredPacks(declared ?? [], packs)) {
72	    const id = packEntryId(entry);
73	    const pack = id === undefined ? undefined : byId.get(id);
74	    if (!pack || plan.some((p) => p.id === id)) continue;      // a local pack, or already planned
75	    const from = installed?.packVersions?.[id];
76	    const to = pack.version;
77	    const needs = pack.minEngineVersion;
78	    const blocked = typeof needs === 'number' && needs > engineVersion
79	      ? `pack "${id}" version ${to} needs engine ${needs}; this repo runs engine ${engineVersion}`
80	      : null;
81	    plan.push({
82	      id,
83	      from: typeof from === 'number' ? from : null,
84	      to: typeof to === 'number' ? to : null,
85	      blocked,
86	      records: packRecordsInGap(id, installed, { today }),
87	    });
88	  }
89	  return plan;
90	}
91	
92	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
93	
