27	// The due tasks, each paired with the slot it runs under. Union the discovered
28	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
29	// frequencies back to their tasks. A task whose frequency isn't due drops out.
30	//
31	// A run carrying FORCE_TASKS evaluates ONLY the forced tasks (#749). The operator
32	// pressed a button that names specific work; running whatever else happened to be
33	// due at that minute alongside it would make the button's effect depend on WHEN it
34	// was pressed — and a fleet fan-out that fires twenty members' schedulers must mean
35	// exactly one task in each, not one task plus each member's coincident backlog.
36	// The skipped due work is not lost: the forced run is excluded from the run ledger's
37	// success watermark question only in the sense that any due slot it did not run
38	// stays due, and the next scheduled run picks it up (dueSlots' most-recent-slot
39	// math never needed this run to happen).
40	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess, forced = []) {
41	  if (forced.length) {
42	    // Each forced task runs under its most-recent slot even though that slot has
43	    // already been run (or, for a `manual` task, never fires on its own at all).
44	    // This gate is the reason forcing has to live here: the due list is computed
45	    // BEFORE any precondition, so a task whose slot has passed is never looked at
46	    // again — and a mid-day forced run is the only kind that matters (#515).
47	    // `planRun` then skips its precondition outright.
48	    return tasks.filter((t) => forced.includes(t.id)).map((task) => {
49	      const s = mostRecentSlot(task.decl.frequency, schedule, now);
50	      return { task, slotId: s.id, slotTime: s.time, forced: true };
51	    });
52	  }
53	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
54	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
55	  const out = [];
56	  for (const task of tasks) {
57	    const slot = due.get(task.decl.frequency);
58	    if (slot) out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime });
59	  }
60	  return out;
61	}
