63	// The verdict a forced task gets INSTEAD of its precondition. The context line
64	// is generic on purpose — it names the mechanism, not the task — and it is there
65	// because a dispatch issue's Context is the agent's binding scope: a forced
66	// dispatch that carried none would read as a scope of nothing, and the agent
67	// should know it arrived by a hand-started run rather than a met condition.
68	const FORCED_VERDICT = Object.freeze({
69	  run: true,
70	  reason: 'forced by FORCE_TASKS on a manual scheduler run — its precondition was not evaluated',
71	  context: Object.freeze(['This run was forced manually (FORCE_TASKS on a workflow_dispatch); the task\'s own precondition was not evaluated, so nothing here asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.']),
72	});
73	
74	// The task ids a manual run forced, out of the opaque override bag. This is the
75	// ONE key the engine reads from that bag, and it is deliberately generic: it
76	// learns "run these task ids", never what any of them do. No task declaration
77	// mentions forcing, and no precondition is consulted for a forced task — an id
78	// matching no discovered task simply forces nothing.
79	export function forcedTaskIds(overrides = {}) {
80	  return String(overrides.FORCE_TASKS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
81	}
