83	// The union of signal names the due tasks declare — the scheduler collects only
84	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
85	export function signalsUnion(dueTaskSlots) {
86	  const names = new Set();
87	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
88	  return [...names];
89	}
90	
91	// The signal-collection lookback: the widest due task's period plus 1h slack
92	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
93	const FREQUENCY_MS = {
94	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
95	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
